function initDataTable(){LoadGridData({tableId:"#dt_insurancetype",url:globalvar.listingURL,columns:columnsConfig,extraParams:[{name:"searchText",value:$("#txtSearch").val()}]})}function SetIDs(){var n=$("#drpCompanies").val();$("#AssociationWithCompanyIDs").val(n)}const columnsConfig=[{data:"InsuranceType",bSortable:!0},{data:"CreatedOn",bSortable:!0,render:function(n){return n?moment(n).format("MM/DD/YYYY hh:mm A"):""}},{data:"UpdatedOn",bSortable:!0,render:function(n){return n?moment(n).format("MM/DD/YYYY hh:mm A"):""}},{data:"IsActive",bSortable:!0,defaultContent:"",className:"text-center",render:function(n){return n?'<span class="label font-weight-bold label-lg label-light-primary label-inline">Active<\/span>':'<span class="label font-weight-bold label-lg label-light-danger label-inline">Inactive<\/span>'}},{title:"Actions",bSortable:!1,width:"170px",defaultContent:"",className:"text-center",render:function(n,t,i){let r=parseInt(i.InsuranceTypeId,10);return'<a href="/InsuranceType/Edit/'+r+'" class="btn btn-sm btn-icon btn-lg-light btn-text-primary btn-hover-light-primary mr-3"><i class="flaticon-edit"><\/i><\/a><a href="javascript:;" class="btn btn-sm btn-icon btn-lg-light btn-text-danger btn-hover-light-danger" onclick="DeleteConfirmationWithTypeDelete('+r+",'InsuranceType','Insurance Type')\"><i class=\"flaticon-delete\"><\/i><\/a>"}}];$(function(){globalvar.IsformView||initDataTable();parseInt(globalvar.rowsaffected)>0?toastr.success(globalvar.tostarMsg):parseInt(globalvar.rowsaffected)==0&&toastr.error(globalvar.tostarMsg)});$("#txtSearch").on("keyup",function(){initDataTable()});